package com.tekwatt.user.service;import com.tekwatt.user.dto.*;import com.tekwatt.user.entity.*;import com.tekwatt.user.repository.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;@Service @Transactional public class UserDirectoryService{private final PartnerRepository partners;private final TechnicianRepository technicians;private final RfidCardRepository cards;public UserDirectoryService(PartnerRepository p,TechnicianRepository t,RfidCardRepository c){partners=p;technicians=t;cards=c;}public Partner savePartner(UUID id,PartnerRequest r){Partner p=id==null?new Partner(r.tenantId(),r.companyName(),r.contactName(),r.email(),r.phone(),r.commissionPercent()):partners.findById(id).orElseThrow(()->notFound("Partner"));if(id!=null)p.update(r.companyName(),r.contactName(),r.email(),r.phone(),r.commissionPercent(),r.status()==null?"ACTIVE":r.status());return partners.save(p);}@Transactional(readOnly=true)public List<Partner>partners(UUID t){return partners.findAllByTenantIdOrderByCreatedAtDesc(t);}public void deletePartner(UUID id){partners.deleteById(id);}public Technician saveTechnician(UUID id,TechnicianRequest r){Technician t=id==null?new Technician(r.tenantId(),r.name(),r.email(),r.phone(),r.skills()):technicians.findById(id).orElseThrow(()->notFound("Technician"));if(id!=null)t.update(r.name(),r.email(),r.phone(),r.skills(),r.status()==null?"ACTIVE":r.status());return technicians.save(t);}@Transactional(readOnly=true)public List<Technician>technicians(UUID t){return technicians.findAllByTenantIdOrderByCreatedAtDesc(t);}public void deleteTechnician(UUID id){technicians.deleteById(id);}public RfidCard issue(RfidCardRequest r){if(cards.existsByCardUidIgnoreCase(r.cardUid()))throw new ResponseStatusException(HttpStatus.CONFLICT,"RFID UID already exists");return cards.save(new RfidCard(r.tenantId(),r.cardUid(),r.label(),r.userId(),r.notes()));}@Transactional(readOnly=true)public List<RfidCard>cards(UUID t){return cards.findAllByTenantIdOrderByIssuedAtDesc(t);}public RfidCard cardStatus(UUID id,String s){RfidCard c=cards.findById(id).orElseThrow(()->notFound("RFID card"));c.status(s.toUpperCase());return c;}private ResponseStatusException notFound(String n){return new ResponseStatusException(HttpStatus.NOT_FOUND,n+" not found");}}
